SELECT q.id,q.bank_id,q.question_type,q.stem,q.answer_text,q.analysis,q.tags,q.source,q.difficulty,q.score,q.sort_no,q.status FROM question_item q JOIN question_bank b ON b.id=q.bank_id
q.bank_id=#{bankId} AND b.published=TRUE AND q.status='ENABLED' AND q.stem LIKE CONCAT('%',#{query.keyword},'%')
ORDER BY q.sort_no ASC,q.id ASC LIMIT #{query.pageSize} OFFSET #{query.offset}
